output_text:
[
  {
    "id": "must_take_entrance_cart",
    "text": "A shopper must collect the entrance cart before completing the trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_cell": "at(1,5)"
      },
      "events": {
        "collects_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_cell",
              "cartAt(1,5)",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "collects_entrance_cart"
    }
  },
  {
    "id": "no_hand_shopping",
    "text": "Items may not be carried by hand; item pickup is only acceptable while the shopper has the cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "hand_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "handFull",
          "hand_pickup"
        ]
      }
    }
  },
  {
    "id": "return_cart_to_front",
    "text": "After taking a cart, the shopper must return it to the front cart-return point before the trip ends.",
    "abstraction": {
      "state_properties": {
        "front_cart_return_cell": "at(0,1)",
        "cart_parked_front": "cartAt(0,1)"
      },
      "events": {
        "takes_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "returns_cart_front": {
          "pre": {
            "and": [
              "front_cart_return_cell",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_front"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "takes_cart",
      "discharge": "returns_cart_front"
    }
  },
  {
    "id": "no_cart_abandonment",
    "text": "A cart may only be left at the designated front return point.",
    "abstraction": {
      "state_properties": {
        "front_cart_return_cell": "at(0,1)"
      },
      "events": {
        "leaves_cart_elsewhere": {
          "pre": {
            "and": [
              "LEAVE_CART",
              {
                "not": "front_cart_return_cell"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leaves_cart_elsewhere"
    }
  },
  {
    "id": "exit_only_after_cart_return",
    "text": "The shopper must not exit unless the cart has already been parked at the front return point.",
    "abstraction": {
      "state_properties": {
        "cart_parked_front": "cartAt(0,1)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "cart_parked_front"
          }
        ]
      }
    }
  },
  {
    "id": "checkout_on_foot",
    "text": "After returning the cart, the shopper must leave the store on foot rather than with the cart.",
    "abstraction": {
      "state_properties": {
        "front_cart_return_cell": "at(0,1)",
        "cartless": {
          "not": "hasCart"
        },
        "exit_cell": "at(9,5)"
      },
      "events": {
        "returns_cart_front": {
          "pre": {
            "and": [
              "front_cart_return_cell",
              "LEAVE_CART"
            ]
          },
          "post": "cartAt(0,1)"
        },
        "exits_on_foot": {
          "pre": {
            "and": [
              "exit_cell",
              "cartless",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "returns_cart_front",
      "discharge": "exits_on_foot"
    }
  },
  {
    "id": "no_post_return_interactions",
    "text": "Once the cart is parked at the front return point, the shopper should proceed to the exit without doing any further store interactions.",
    "abstraction": {
      "state_properties": {
        "cart_parked_front": "cartAt(0,1)"
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "cart_parked_front",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  },
  {
    "id": "do_not_push_cart_past_return",
    "text": "At the front return point, the shopper may not continue moving with the cart and must leave it there before proceeding.",
    "abstraction": {
      "state_properties": {
        "front_cart_return_cell": "at(0,1)",
        "still_pushing_cart": "hasCart"
      },
      "events": {
        "moves_past_return_with_cart": {
          "pre": {
            "and": [
              "front_cart_return_cell",
              "still_pushing_cart",
              "MOVE"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "moves_past_return_with_cart"
    }
  }
]
